// AWI: diagnosa kalkulator 2 sementara (hapus setelah dipakai)
add_action('rest_api_init', function () {
	register_rest_route('awi/v1', '/calcdiag2', array(
		'methods' => 'GET',
		'permission_callback' => function () { return current_user_can('manage_options'); },
		'callback' => function ($req) {
			global $wpdb;
			$w = $req->get_param('w');
			$out = array();
			$cut = function ($s, $needle, $before, $len) { $i = strpos($s, $needle); if ($i === false) return null; return substr($s, max(0, $i - $before), $len); };
			if ($w === 'snip') {
				foreach (array(13, 24) as $id) {
					$c = $wpdb->get_var($wpdb->prepare("SELECT code FROM {$wpdb->prefix}snippets WHERE id=%d", $id));
					$out[$id] = $cut($c, 'Atto 1', 400, 3800);
				}
				$c = $wpdb->get_var("SELECT code FROM {$wpdb->prefix}snippets WHERE id=29");
				$out['29'] = $cut($c, 'BYD Atto 1 Standard', 300, 2600);
			} elseif ($w === 'pages') {
				foreach (array(10295 => 'Atto 1 Standard', 10303 => "'Atto 1'", 10802 => 'Atto 1 Standard') as $id => $n) {
					$c = get_post_field('post_content', $id);
					$out[$id] = $cut($c, $n, 200, $id == 10303 ? 4200 : 2600);
				}
			} else {
				$c = get_post_field('post_content', 10706);
				$out['spec'] = $cut(wp_strip_all_tags($c), 'Spesifikasi Lengkap', 0, 2600);
			}
			return $out;
		},
	));
});
